-- Supabase → SQL Editor'a yapıştırıp Run'a basın. Tek seferde, hata olursa hiçbir şey değişmez.
begin;

-- 1) Yedek: mevcut menü bu tablolara kopyalanır (geri dönmek için).
drop table if exists backup_items; drop table if exists backup_categories;
create table backup_categories as select * from categories;
create table backup_items as select * from items;
revoke all on backup_categories, backup_items from anon, authenticated;

-- 2) Alerjen bilgisi girilmemiş ürünler 'alerjen içermez' gibi görünmesin diye boş (null) bırakılabilmeli.
alter table items alter column allergens drop not null;
alter table items alter column allergens drop default;

-- 3) Eski menüyü temizle ve yenisini yükle.
delete from items; delete from categories;



-- 4) Test amaçlı girilmiş duyuru ve günün balıkları metinlerini temizle.
update settings set notice_tr = null, notice_en = null, catch_tr = null, catch_en = null where id = 1;

commit;

